import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`tree-service-estimate`,heroTitle:`Generate tree service estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded tree service scope, photos, and site notes, then drafts a detailed estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload tree service details`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded tree service photos, inspection notes, or a customer scope. Build a complete tree service estimate. (1) Extract tree count, species or size notes, access constraints, hazards, cleanup needs, equipment requirements, and disposal considerations from the uploaded files. (2) Estimate crew hours, equipment, hauling, permits, and subcontractor needs. (3) Build pricing options with assumptions, exclusions, emergency-work notes, and margin. (4) Highlight customer decisions or site-verification items that could change the quote. (5) Deliver a customer-ready tree service estimate with line-item pricing, scope summary, and next steps.`,heroOverlaySteps:[`Extracting tree count, access constraints, hazards, and cleanup needs from your files`,`Sizing crew hours, equipment, hauling, permits, and disposal requirements`,`Building pricing options with assumptions, exclusions, and margin`,`Customer-ready tree service estimate with scope summary, ready to send`],generatingSteps:[`Reading the uploaded tree service photos, inspection notes, and customer scope`,`Designing an agent to organize site constraints, labor, equipment, and disposal needs`,`Configuring estimate logic for assumptions, exclusions, permits, and emergency work`,`Preparing a detailed tree service estimate with line items and next steps`],featureSectionTitle:`From site notes to customer-ready estimate`,featureCardTitles:[`Connects to your estimating workflow`,`Estimates built around the job site`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Photos, inspection notes, spreadsheets, and internal planning docs stay connected so estimating and revisions move faster.`,`Tree count. Access constraints. Equipment. Cleanup. Computer gives your team a tree service estimate draft that is ready for customer review.`],capabilitySectionTitle:`Your tree service estimator, on autopilot`,capabilitySectionSubtitle:`Upload the scope, get back a tree service estimate built around the real property conditions.`,capabilityCards:[{title:`Site Scope Extraction`,description:`Computer can extract tree count, size notes, access constraints, hazards, and cleanup needs from uploaded photos and service notes.`},{title:`Crew & Equipment Planning`,description:`Computer can estimate crew hours, bucket truck needs, rigging requirements, hauling, and disposal so the estimate reflects the actual work.`},{title:`Pricing Options`,description:`Computer can turn the scope into clear pricing with assumptions, exclusions, permit notes, and optional emergency or cleanup add-ons.`},{title:`Connect Your Tools`,description:`Computer can keep estimate drafts organized across docs, sheets, uploaded files, and internal workflows so review and handoff are easy.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred labor rates, disposal assumptions, and estimate structure across sessions so quotes stay consistent.`},{title:`Revision Support`,description:`Computer can update the estimate when the customer adds trees, changes cleanup expectations, or asks for alternate service levels.`}]});export{t as default};
